    // Clone the mesh and bake its world transform into the geometry
    const clone = mesh.clone();
    clone.geometry = mesh.geometry.clone();
    clone.geometry.applyMatrix4(mesh.matrixWorld);

    // Reset the clone's local transform since world is baked in
