    tempScene.add(clone);

    return exporter.parse(tempScene);
}

/**
 * Collect all meshes within a group (recursively), returning them as a flat array.
 */
function collectMeshes(group) {
    const meshes = [];
    group.traverse((child) => {
        if (child.isMesh) {
            meshes.push(child);
        }
    });
    return meshes;
}

